```javascript
function chunk(array, size) {
  if (!size || size <= 0) throw new Error('Size must be a positive integer');
  const result = [];
  for (let i = 0; i < array.length; i += size) {
    result.push(array.slice(i, i + size));
  }
  return result;
}

